   if(patientWorkspace()){nav.getMenu().add(0,1,0,t("search")).setIcon(android.R.drawable.ic_menu_search);nav.getMenu().add(0,2,1,t("bookings")).setIcon(android.R.drawable.ic_menu_agenda);nav.getMenu().add(0,3,2,t("map")).setIcon(android.R.drawable.ic_menu_mylocation);}
