 private ArrayList<JSONObject> pharmacyList(){ArrayList<JSONObject> result=new ArrayList<>();for(JSONObject p:list(rows("pharmacies")))if(p.optString("city").equals(city)&&!p.optBoolean("pilot")&&(!night||p.optBoolean("duty")))result.add(p);Set<String> saved=savedPharmacies();int radius=experiencePrefs().getInt("radius",0);for(Iterator<JSONObject> it=result.iterator();it.hasNext();){JSONObject p=it.next();String name=(p.optString("name")+" "+p.optString("area")).toLowerCase(Locale.ROOT);boolean fresh=false;if(availableOnly&&screen.equals("results"))for(JSONObject reply:list(rows("responses")))if(reply.optString("request").equals(activeRequest)&&reply.optString("pharmacy").equals(p.optString("id"))&&reply.optString("status").equals("yes")&&reply.optLong("updated")>System.currentTimeMillis()-1800000)fresh=true;if((radius>0&&distance(p)>radius*1000)||(!pharmacyFilter.isEmpty()&&!name.contains(pharmacyFilter.toLowerCase(Locale.ROOT)))||(savedOnly&&!saved.contains(p.optString("id")))||(availableOnly&&screen.equals("results")&&!fresh))it.remove();}Collections.sort(result,(a,b)->Double.compare(distance(a),distance(b)));return result;}
 private double distance(JSONObject p){float[] result=new float[1];JSONObject origin=center();Location.distanceBetween(position==null?origin.optDouble("lat"):position.getLatitude(),position==null?origin.optDouble("lng"):position.getLongitude(),p.optDouble("lat"),p.optDouble("lng"),result);return result[0];}
