 private void bookings(){content.addView(heading(experience("activity")));button(experience("filters"),content,this::trackingFilters,false);button(experience("refresh"),content,()->load(false),false);if(rows("reservations").length()==0)notice(content,t("noBookings"));int visibleBookings=0;for(JSONObject b:list(rows("reservations"))){String effective=b.optString("status").equals("active")&&b.optLong("expires")<=System.currentTimeMillis()?"expired":b.optString("status");if((!bookingFilter.isEmpty()&&!bookingFilter.equals(effective))||(!bookingQuery.isEmpty()&&!b.optString("medicine").toLowerCase(Locale.ROOT).contains(bookingQuery.toLowerCase(Locale.ROOT)))||(bookingDays>0&&b.optLong("created")<System.currentTimeMillis()-bookingDays*86400000L))continue;visibleBookings++;LinearLayout c=card(content);c.addView(text(b.optString("medicine"),20,NAVY));String status=b.optString("status");if(status.equals("active")&&b.optLong("expires")<System.currentTimeMillis())status="expired";c.addView(text(t(status),15,GREEN));JSONObject p=pharmacyById(b.optString("pharmacy"));if(p!=null)c.addView(text(p.optString("name"),16,MUTED));if(status.equals("active")){long minutes=Math.max(0,(b.optLong("expires")-System.currentTimeMillis())/60000);c.addView(text(t("timeLeft")+": "+minutes+" "+t("minutes"),16,NAVY));button(t("showQr"),c,()->bookingQr(b),true);if(p!=null){button(t("details"),c,()->details(p),false);if(!p.optBoolean("pilot"))button(sharing.equals(b.optString("id"))?t("stopSharing"):t("shareTrip"),c,()->{if(sharing.equals(b.optString("id")))stopSharing();else confirm(t("shareTripNote"),()->locate(()->{sharing=b.optString("id");sharePosition();render();}));},false);}button(t("cancelBooking"),c,()->confirm(t("cancelQuestion"),()->mutate(obj("action","cancel","reservation",b.optString("id")),null)),false);}}
  if(visibleBookings==0)notice(content,experience("noResults"));content.addView(heading(t("mySearches")));for(JSONObject r:list(rows("requests"))){if((!bookingQuery.isEmpty()&&!r.optString("medicine").toLowerCase(Locale.ROOT).contains(bookingQuery.toLowerCase(Locale.ROOT)))||(bookingDays>0&&r.optLong("created")<System.currentTimeMillis()-bookingDays*86400000L))continue;String state=r.optInt("stopped")>0?"stopped":r.optLong("created")<=System.currentTimeMillis()-86400000?"expired":"pending";if(state.equals("pending"))for(JSONObject reply:list(rows("responses")))if(reply.optString("request").equals(r.optString("id"))&&reply.optString("status").equals("yes")&&reply.optLong("updated")>System.currentTimeMillis()-1800000)state="available";button(r.optString("medicine")+" · "+experience(state),content,()->{activeRequest=r.optString("id");query=r.optString("medicine");city=r.optString("city");screen="results";render();},false);}}
 private void bookingQr(JSONObject b){LinearLayout c=column();c.setPadding(dp(24),dp(16),dp(24),dp(16));TextView code=text(b.optString("code"),24,NAVY);code.setTextIsSelectable(true);c.addView(code);try{BitMatrix matrix=new MultiFormatWriter().encode("DAWA:"+b.optString("id")+":"+b.optString("code"),BarcodeFormat.QR_CODE,600,600);Bitmap bitmap=Bitmap.createBitmap(600,600,Bitmap.Config.RGB_565);for(int y=0;y<600;y++)for(int x=0;x<600;x++)bitmap.setPixel(x,y,matrix.get(x,y)?Color.BLACK:Color.WHITE);ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setContentDescription(t("pickupCode"));c.addView(image,new LinearLayout.LayoutParams(-1,dp(240)));}catch(Exception ignored){}c.addView(text(t("prescription"),16,MUTED));new MaterialAlertDialogBuilder(this).setTitle(t("pickupCode")).setView(c).setPositiveButton(t("close"),null).show();}
