 private void pharmacy(){content.addView(heading(t("pharmacyTitle")));JSONObject p=own();if(p==null||p.optString("status").equals("rejected")){registration(p);return;}if(!p.optString("status").equals("approved")){notice(content,t(p.optString("status").equals("suspended")?"applicationSuspended":"applicationPending"));button(t("refresh"),content,()->load(false),false);return;}notice(content,p.optString("name"));CheckBox duty=new CheckBox(this);duty.setText(t("duty"));duty.setChecked(p.optInt("duty")==1);duty.setOnCheckedChangeListener((v,on)->mutate(obj("action","duty","pharmacy",p.optString("id"),"enabled",on),null));content.addView(duty);button(t("refresh"),content,()->load(false),false);LinearLayout tabs=new LinearLayout(this);content.addView(tabs);for(String tab:new String[]{"inbox","pickup","stock"}){MaterialButton item=button(t(tab),tabs,()->{pharmacyTab=tab;render();},pharmacyTab.equals(tab));item.setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));}if(pharmacyTab.equals("inbox")){content.addView(heading(t("inbox")));for(JSONObject r:list(rows("staffRequests"))){LinearLayout c=card(content);c.addView(text(r.optString("medicine"),20,NAVY));button(t("markYes"),c,()->mutate(obj("action","reply","request",r.optString("id"),"pharmacy",p.optString("id"),"available",true),null),true);button(t("markNo"),c,()->mutate(obj("action","reply","request",r.optString("id"),"pharmacy",p.optString("id"),"available",false),null),false);}if(rows("staffRequests").length()==0)notice(content,t("noInbox"));}if(pharmacyTab.equals("pickup")){content.addView(heading(t("pickup")));if(rows("staffBookings").length()==0)notice(content,t("noBookings"));for(JSONObject b:list(rows("staffBookings"))){LinearLayout c=card(content);c.addView(text(b.optString("medicine"),18,NAVY));if(!b.isNull("approachLat"))c.addView(text(t("approaching"),14,GREEN));if(!b.isNull("approachLat")&&!b.isNull("approachLng"))button(extra("خريطة الاقتراب","Carte d’approche","Arrival map","Takarḍa n tuɣalin"),c,()->{arrivalBooking=b.optString("id");destination=null;screen="map";render();},false);button(t("verify"),c,()->collect(b),true);}}if(pharmacyTab.equals("stock")){inventory();}}
