 private String pharmacyFilter="",bookingFilter="",bookingQuery="",stockFilter="all",stockQuery="",stockSort="newest";private boolean savedOnly=false,availableOnly=false;private int stockPage=0,bookingDays=0;
 private SharedPreferences experiencePrefs(){JSONObject p=data.optJSONObject("profile");return getSharedPreferences("lqadwa-experience:"+(p==null?"anonymous":p.optString("id","anonymous")),MODE_PRIVATE);}
 private boolean largeText(){return experiencePrefs().getBoolean("largeText",false);}
 private Set<String> savedPharmacies(){return new HashSet<>(experiencePrefs().getStringSet("favorites",Collections.emptySet()));}
 private boolean stockScreen(){return screen.equals("pharmacy")&&pharmacyTab.equals("stock");}
 private void moveMap(org.maplibre.android.camera.CameraUpdate update){if(map==null)return;if(experiencePrefs().getBoolean("lessMotion",false))map.moveCamera(update);else map.animateCamera(update);}
 private void clientFilters(){
  LinearLayout form=column();form.setPadding(dp(20),dp(12),dp(20),dp(20));EditText name=field(form,experience("pharmacyName"),pharmacyFilter,InputType.TYPE_CLASS_TEXT);
  form.addView(text(experience("radius"),16,NAVY));Spinner radius=new Spinner(this);String[] labels={experience("any"),"1 km","3 km","5 km","10 km","20 km","50 km"};int[] ranges={0,1,3,5,10,20,50};radius.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));for(int i=0;i<ranges.length;i++)if(ranges[i]==experiencePrefs().getInt("radius",0))radius.setSelection(i);form.addView(radius);
  CheckBox saved=new CheckBox(this);saved.setText(experience("favorites"));saved.setChecked(savedOnly);form.addView(saved);CheckBox available=new CheckBox(this);available.setText(t("availableOnly"));available.setChecked(availableOnly);if(screen.equals("results"))form.addView(available);
  new MaterialAlertDialogBuilder(this).setTitle(experience("filters")).setView(form).setNegativeButton(t("cancel"),null).setNeutralButton(experience("reset"),(d,w)->{pharmacyFilter="";savedOnly=false;availableOnly=false;night=false;experiencePrefs().edit().putInt("radius",0).apply();render();}).setPositiveButton(t("save"),(d,w)->{pharmacyFilter=name.getText().toString().trim();savedOnly=saved.isChecked();availableOnly=available.isChecked();experiencePrefs().edit().putInt("radius",ranges[radius.getSelectedItemPosition()]).apply();render();}).show();
 }
 private void trackingFilters(){LinearLayout form=column();form.setPadding(dp(20),dp(12),dp(20),dp(20));EditText name=field(form,experience("medicine"),bookingQuery,InputType.TYPE_CLASS_TEXT);String[] keys={"","active","collected","cancelled","expired"};Spinner status=new Spinner(this);status.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{experience("any"),experience("active"),experience("collected"),experience("cancelled"),experience("expired")}));for(int i=0;i<keys.length;i++)if(keys[i].equals(bookingFilter))status.setSelection(i);form.addView(status);Spinner days=new Spinner(this);days.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{experience("any"),experience("last7"),experience("last30")}));days.setSelection(bookingDays==7?1:bookingDays==30?2:0);form.addView(days);new MaterialAlertDialogBuilder(this).setTitle(experience("filters")).setView(form).setNegativeButton(t("cancel"),null).setNeutralButton(experience("reset"),(d,w)->{bookingFilter="";bookingQuery="";bookingDays=0;render();}).setPositiveButton(t("save"),(d,w)->{bookingQuery=name.getText().toString().trim();bookingFilter=keys[status.getSelectedItemPosition()];bookingDays=days.getSelectedItemPosition()==1?7:days.getSelectedItemPosition()==2?30:0;render();}).show();}
 private void displaySettings(){LinearLayout form=column();form.setPadding(dp(20),dp(12),dp(20),dp(20));notice(form,experience("local"));CheckBox large=new CheckBox(this);large.setText(experience("largeText"));large.setChecked(largeText());form.addView(large);CheckBox less=new CheckBox(this);less.setText(experience("lessMotion"));less.setChecked(experiencePrefs().getBoolean("lessMotion",false));form.addView(less);form.addView(text(experience("refreshRate"),16,NAVY));Spinner rate=new Spinner(this);int[] values={0,30,60,120};rate.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{experience("manual"),"30 s","60 s","120 s"}));for(int i=0;i<values.length;i++)if(experiencePrefs().getInt("refresh",30)==values[i])rate.setSelection(i);form.addView(rate);new MaterialAlertDialogBuilder(this).setTitle(experience("settings")).setView(form).setNegativeButton(t("cancel"),null).setNeutralButton(experience("resetPrefs"),(d,w)->{experiencePrefs().edit().putBoolean("largeText",false).putBoolean("lessMotion",false).putInt("refresh",30).putInt("radius",0).apply();restartRefresh();render();}).setPositiveButton(t("save"),(d,w)->{experiencePrefs().edit().putBoolean("largeText",large.isChecked()).putBoolean("lessMotion",less.isChecked()).putInt("refresh",values[rate.getSelectedItemPosition()]).apply();restartRefresh();render();}).show();}
 private void restartRefresh(){handler.removeCallbacks(refreshLoop);int seconds=experiencePrefs().getInt("refresh",30);if(resumed&&seconds>0)handler.postDelayed(refreshLoop,seconds*1000L);}
 private String stockCsv="",stockCsvSession="";
 private String csvCell(String value){String text=value;String trimmed=text.trim();if((!trimmed.isEmpty()&&"=+@-".indexOf(trimmed.charAt(0))>=0)||text.startsWith("\t")||text.startsWith("\r")||text.startsWith("\n"))text="'"+text;return "\""+text.replace("\"","\"\"")+"\"";}
 private void exportStockPage(JSONArray items){StringBuilder csv=new StringBuilder("\uFEFF");csv.append(csvCell(experience("medicine"))).append(',').append(csvCell(experience("quantity"))).append(',').append(csvCell(experience("updated"))).append("\r\n");for(JSONObject item:list(items))csv.append(csvCell(item.optString("name"))).append(',').append(csvCell(item.optString("quantity"))).append(',').append(csvCell(String.valueOf(item.optLong("updated")))).append("\r\n");stockCsv=csv.toString();stockCsvSession=token;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("text/csv");intent.putExtra(Intent.EXTRA_TITLE,"lqadwa-stock-page.csv");startActivityForResult(intent,73);}
