 private void inventoryFilters(){LinearLayout form=column();form.setPadding(dp(20),dp(12),dp(20),dp(20));EditText query=field(form,experience("medicine"),stockQuery,InputType.TYPE_CLASS_TEXT);EditText threshold=field(form,experience("threshold"),String.valueOf(experiencePrefs().getInt("threshold",5)),InputType.TYPE_CLASS_NUMBER);String[] keys={"all","low","out","in"},sorts={"newest","name","quantity"};Spinner state=new Spinner(this);state.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{experience("any"),experience("low"),experience("out"),experience("in")}));for(int i=0;i<keys.length;i++)if(keys[i].equals(stockFilter))state.setSelection(i);form.addView(state);Spinner order=new Spinner(this);order.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{experience("newest"),experience("nameSort"),experience("qtySort")}));for(int i=0;i<sorts.length;i++)if(sorts[i].equals(stockSort))order.setSelection(i);form.addView(order);androidx.appcompat.app.AlertDialog dialog=new MaterialAlertDialogBuilder(this).setTitle(experience("filters")).setView(form).setNegativeButton(t("cancel"),null).create();button(t("save"),form,()->{int n;try{n=Integer.parseInt(threshold.getText().toString());if(n<1||n>100)throw new Exception();}catch(Exception e){threshold.setError(experience("threshold"));return;}stockQuery=query.getText().toString().trim();stockFilter=keys[state.getSelectedItemPosition()];stockSort=sorts[order.getSelectedItemPosition()];stockPage=0;experiencePrefs().edit().putInt("threshold",n).apply();dialog.dismiss();render();},true);dialog.show();}
