 private void loadInventory(){if(!stockScreen())return;long sequence=++stockSequence;LinearLayout container=inventoryRows;if(container==null){container=column();inventoryRows=container;content.addView(container);}LinearLayout target=container;request("/api/stock?q="+Uri.encode(stockQuery)+"&filter="+stockFilter+"&sort="+stockSort+"&page="+stockPage+"&threshold="+experiencePrefs().getInt("threshold",5),null,r->{if(sequence!=stockSequence||!stockScreen()||inventoryRows!=target)return;target.removeAllViews();JSONObject totals=r.optJSONObject("summary");if(totals!=null)notice(target,experience("total")+": "+totals.optInt("total")+" · "+experience("units")+": "+totals.optInt("units")+"\n"+experience("low")+": "+totals.optInt("low")+" · "+experience("out")+": "+totals.optInt("out"));JSONArray items=r.optJSONArray("rows");if(items==null)return;if(items.length()>0)button(experience("export"),target,()->exportStockPage(items),false);for(JSONObject item:list(items)){LinearLayout c=card(target);c.addView(heading(item.optString("name")));int qty=item.optInt("quantity");c.addView(text(qty+" · "+experience(qty==0?"out":qty<=experiencePrefs().getInt("threshold",5)?"low":"in"),17,qty==0?MUTED:GREEN));c.addView(text(experience("updated")+": "+new Date(item.optLong("updated")).toLocaleString(),14,MUTED));LinearLayout controls=new LinearLayout(this);c.addView(controls);MaterialButton minus=button("−1",controls,()->saveStock(obj("action","edit","id",item.optString("id"),"updated",item.optLong("updated"),"name",item.optString("name"),"quantity",qty-1)),false);minus.setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));minus.setEnabled(qty>0);MaterialButton plus=button("+1",controls,()->saveStock(obj("action","edit","id",item.optString("id"),"updated",item.optLong("updated"),"name",item.optString("name"),"quantity",qty+1)),false);plus.setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));plus.setEnabled(qty<9999);button(experience("edit"),c,()->stockEditor(item),false);button(experience("remove"),c,()->confirm(experience("confirmDelete"),()->saveStock(obj("action","delete","id",item.optString("id"),"updated",item.optLong("updated")))),false);}if(items.length()==0)notice(target,experience("noResults"));int total=r.optInt("total");notice(target,(stockPage+1)+" / "+Math.max(1,(total+49)/50));if(stockPage>0)button(experience("previous"),target,()->{stockPage--;loadInventory();},false);if((stockPage+1)*50<total)button(experience("next"),target,()->{stockPage++;loadInventory();},false);});}
