 private void editDetails(boolean pharmacy){
  request("/api/profile",null,value->{
   JSONObject original=value.optJSONObject(pharmacy?"pharmacy":"details");if(original==null){error(t("error"));return;}
   LinearLayout form=column();form.setPadding(dp(20),dp(12),dp(20),dp(20));
   String[] keys=pharmacy?new String[]{"contactName","contactEmail","municipality","accessNotes"}:new String[]{"firstName","lastName","phone","municipality","address","age","jobTitle"};
   Map<String,EditText> fields=new LinkedHashMap<>();
   for(String key:keys)fields.put(key,field(form,detailLabel(key),original.isNull(key)?"":original.optString(key),key.equals("age")?InputType.TYPE_CLASS_NUMBER:key.equals("phone")?InputType.TYPE_CLASS_PHONE:key.equals("contactEmail")?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS:InputType.TYPE_CLASS_TEXT));
   CheckBox access=new CheckBox(this);if(pharmacy){access.setText(detailLabel("wheelchairAccess"));access.setChecked(original.optBoolean("wheelchairAccess"));form.addView(access);}
   JSONObject health=value.optJSONObject("health");Map<String,EditText> notes=new LinkedHashMap<>();CheckBox share=new CheckBox(this);
   if(!pharmacy&&patientWorkspace()){
    form.addView(heading(detailLabel("health")));notice(form,detailLabel("healthHelp"));
    for(String key:new String[]{"conditions","chronicConditions","allergies"})notes.put(key,field(form,detailLabel(key),health==null?"":health.optString(key),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE));
    share.setText(detailLabel("shareWithOwner"));share.setChecked(health!=null&&health.optBoolean("shareWithOwner"));form.addView(share);
   }
   ScrollView scroll=new ScrollView(this);scroll.addView(form);androidx.appcompat.app.AlertDialog dialog=new MaterialAlertDialogBuilder(this).setTitle(detailLabel(pharmacy?"pharmacyDetails":"personal")).setView(scroll).setNegativeButton(t("cancel"),null).create();
   button(detailLabel("save"),form,()->{
    JSONObject details=new JSONObject();for(Map.Entry<String,EditText> entry:fields.entrySet()){String key=entry.getKey(),text=entry.getValue().getText().toString().trim();if(!pharmacy&&(key.equals("firstName")||key.equals("lastName"))&&text.isEmpty()){entry.getValue().setError(detailLabel(key));return;}try{if(key.equals("age")){if(text.isEmpty())details.put(key,JSONObject.NULL);else{int age=Integer.parseInt(text);if(age<0||age>120)throw new Exception();details.put(key,age);}}else details.put(key,text);}catch(Exception invalid){entry.getValue().setError(detailLabel(key));return;}}
    JSONObject body=obj("action",pharmacy?"pharmacy":"personal","details",details);try{if(pharmacy)details.put("wheelchairAccess",access.isChecked());else if(patientWorkspace()){JSONObject h=new JSONObject();for(Map.Entry<String,EditText> entry:notes.entrySet())h.put(entry.getKey(),entry.getValue().getText().toString().trim());h.put("shareWithOwner",share.isChecked());body.put("health",h);}}catch(JSONException invalid){error(t("error"));return;}
    request("/api/profile",body,result->{dialog.dismiss();load(false);});
   },true);dialog.show();
  });
 }
